code='''def transform(grid):
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                points[value] = (r, c)
    r, c = points[2]
    target_r, target_c = points[1]
    sr = (target_r > r) - (target_r < r)
    sc = (target_c > c) - (target_c < c)
    dr, dc = abs(target_r - r), abs(target_c - c)

    r += sr
    c += sc
    dr -= 1
    dc -= 1
    if grid[r][c] == 0:
        out[r][c] = 3
    if dr > dc:
        for _ in range(dr - dc):
            r += sr
            if grid[r][c] == 0:
                out[r][c] = 3
        dr = dc
    elif dc > dr:
        for _ in range(dc - dr):
            c += sc
            if grid[r][c] == 0:
                out[r][c] = 3
        dc = dr
    while dr > 0:
        r += sr
        c += sc
        if grid[r][c] == 0:
            out[r][c] = 3
        dr -= 1
        dc -= 1
    return out
'''
